pub fn particleAttrSlot(attr_name: []const u8) ?usize {
    if (std.mem.eql(u8, attr_name, "quad_corner")) {
        return 0;
    }
    if (std.mem.eql(u8, attr_name, "inst_pos")) {
        return 1;
    }
    if (std.mem.eql(u8, attr_name, "inst_stroke_size")) {
        return 2;
    }
    if (std.mem.eql(u8, attr_name, "inst_fill_size")) {
        return 3;
    }
    if (std.mem.eql(u8, attr_name, "inst_stroke_a")) {
        return 4;
    }
    if (std.mem.eql(u8, attr_name, "inst_fill_a")) {
        return 5;
    }
    if (std.mem.eql(u8, attr_name, "inst_shape")) {
        return 6;
    }
    return null;
}
